<?php
if(!defined('ABSPATH')){exit;}
/** Read-only Page pilot. All Meta API calls are GET; secrets remain server-side. */
final class WGPP_Facebook {
    const APP='_wgpp_fb_app_v1';const AUTH='_wgpp_fb_auth_v1';const CHOICES='_wgpp_fb_pages_v1';const PAGE='_wgpp_fb_page_v1';const CACHE='_wgpp_fb_reports_v1';
    const SCOPES=['business_management','pages_show_list','pages_read_engagement','read_insights'];
    const IG_SCOPES=['instagram_basic','instagram_manage_insights'];
    const METRIC='page_total_media_view_unique';
    public static function boot(){foreach(['settings','start','callback','discover','select','disconnect','instagram','ig_disconnect'] as $op){add_action('admin_post_wgpp_fb_'.$op,[__CLASS__,$op]);}add_action('wp_ajax_wgpp_facebook',[WGPP_FB_Reports::class,'ajax']);add_action('wp_ajax_wgpp_instagram',[WGPP_IG_Reports::class,'ajax']);}
    public static function callback_url(){return admin_url('admin-post.php?action=wgpp_fb_callback');}
    public static function encrypt($value,$context){return WGPP_Google::encrypt($value,'facebook:'.$context);}
    public static function decrypt($value,$context){return WGPP_Google::decrypt($value,'facebook:'.$context);}
    public static function app(){$saved=get_option(self::APP);if(!$saved){throw new RuntimeException('A site administrator must configure the Westgate Meta application first.');}return self::validate_app(self::decrypt($saved,'application'));}
    public static function validate_app($a){
        if(!is_array($a) || !preg_match('/^[1-9][0-9]{4,29}$/D',$a['id'] ?? '') || !preg_match('/^[a-zA-Z0-9_-]{16,200}$/D',$a['secret'] ?? '') || !preg_match('/^[1-9][0-9]{4,29}$/D',$a['config_id'] ?? '') || !preg_match('/^v[1-9][0-9]{0,2}\.0$/D',$a['version'] ?? '')){throw new RuntimeException('Configure the Westgate Meta app ID, secret, User-token login configuration ID and Graph version first.');}return $a;
    }
    public static function signature($app){return hash('sha256',wp_json_encode($app));}
    public static function save_meta($company,$key,$value){if(!update_post_meta($company,$key,$value) && get_post_meta($company,$key,true)!==$value){throw new RuntimeException('Could not save Facebook connection or reporting data.');}}
    private static function owner(){if(!WGPP_Company::can('connections')){throw new RuntimeException('Company owner access required.');}return WGPP_Company::context();}
    private static function finish($message){set_transient('wgpp_notice_'.get_current_user_id(),$message,120);wp_safe_redirect(WGPP_Company::connection_url(str_contains((string)($_POST['action']??''),'instagram') || str_contains((string)($_POST['action']??''),'ig_disconnect')?'instagram':'facebook'));exit;}
    public static function settings(){
        if(!current_user_can('manage_options')){wp_die('Site administrator access required.','',['response'=>403]);}check_admin_referer('wgpp_fb_settings');
        try{$a=[];foreach(['id','secret','config_id','version'] as $key){$v=$_POST['fb_'.$key] ?? '';if(!is_string($v)){throw new RuntimeException('Invalid Meta application setting.');}$a[$key]=trim(wp_unslash($v));}
            if(!$a['secret']){$old=self::app();if($old['id']!==$a['id']){throw new RuntimeException('A changed app ID requires its matching secret.');}$a['secret']=$old['secret'];}
            self::validate_app($a);if(!update_option(self::APP,self::encrypt($a,'application'),false)){throw new RuntimeException('Could not save Meta application settings.');}self::finish('Westgate Facebook application settings saved.');
        }catch(RuntimeException $e){self::finish($e->getMessage());}
    }
    /** Fixed-host GET only; no provider-supplied URL is followed. */
    public static function get($app,$path,$params=[],$token=null){
        if(!preg_match('~^(oauth/access_token|debug_token|me/(permissions|accounts)|[1-9][0-9]{0,29}(/insights|/published_posts|/media)?)$~D',$path)){throw new RuntimeException('Unsupported Facebook reporting endpoint.');}
        $headers=['Accept'=>'application/json'];if($token && (!is_string($token) || strpbrk($token,"\r\n")!==false)){throw new RuntimeException('Invalid Facebook authorization token.');}if($token){$headers['Authorization']='Bearer '.$token;$params['appsecret_proof']=hash_hmac('sha256',$token,$app['secret']);}
        $url='https://graph.facebook.com/'.$app['version'].'/'.$path.'?'.http_build_query($params,'','&',PHP_QUERY_RFC3986);
        $r=wp_safe_remote_get($url,['timeout'=>15,'redirection'=>0,'limit_response_size'=>1048576,'headers'=>$headers]);
        if(is_wp_error($r)){throw new RuntimeException('Facebook request did not complete. Please retry.');}$body=json_decode(wp_remote_retrieve_body($r),true);$status=wp_remote_retrieve_response_code($r);
        if($status!==200 || !is_array($body) || isset($body['error'])){$error=is_array($body) && is_array($body['error'] ?? null)?$body['error']:[];$code=(int)($error['code'] ?? 0);throw new RuntimeException($code===190?'Facebook authorization expired or was revoked. Reconnect the Page.':'Facebook could not provide this report (HTTP '.(int)$status.', code '.$code.'). Check Page permissions and metric availability.',$code);}
        return $body;
    }
    public static function validate_permissions($data){if(!is_array($data['data'] ?? null)){throw new RuntimeException('Unexpected Facebook permission response.');}$granted=[];foreach($data['data'] as $permission){if(!is_array($permission) || !is_string($permission['permission'] ?? null)){throw new RuntimeException('Unexpected Facebook permission response.');}if(($permission['status'] ?? '')==='granted'){$granted[]=$permission['permission'];}}
        if(array_diff(self::SCOPES,$granted)){throw new RuntimeException('Approve the required business-asset dependency, Page listing, Page read engagement and insights reporting permissions.');}
        if(array_diff($granted,array_merge(self::SCOPES,self::IG_SCOPES,['email','public_profile']))){throw new RuntimeException('Configure this pilot with only the documented business-asset dependency and Page reporting permissions; remove other permissions from the login configuration.');}
    }
    public static function token_lifetime($body,$app,$now){$d=$body['data'] ?? [];if(($d['is_valid'] ?? false)!==true || (string)($d['app_id'] ?? '')!==$app['id'] || ($d['type'] ?? '')!=='USER' || !is_numeric($d['expires_at'] ?? null)){throw new RuntimeException('Meta did not verify a valid User token for this application.');}$end=(int)$d['expires_at'];if($end===0){$end=$now+90*DAY_IN_SECONDS;}if(is_numeric($d['data_access_expires_at'] ?? null) && $d['data_access_expires_at']>0){$end=min($end,(int)$d['data_access_expires_at']);}$ttl=$end-$now;if($ttl<3600 || $ttl>90*DAY_IN_SECONDS){throw new RuntimeException('Meta authorization has less than one hour remaining. Reconnect to continue.');}return $ttl;}
    public static function start(){
        check_admin_referer('wgpp_fb_start');try{$c=self::owner();$a=self::app();if(parse_url(self::callback_url(),PHP_URL_SCHEME)!=='https'){throw new RuntimeException('HTTPS is required for Facebook authorization.');}
            $state=bin2hex(random_bytes(32));$record=['company'=>$c['id'],'user'=>get_current_user_id(),'session'=>hash('sha256',wp_get_session_token()),'app'=>self::signature($a),'expires'=>time()+600];
            WGPP_Native_Reviews::locked($c['id'],static function()use($c,$state,$record){self::save_meta($c['id'],'_wgpp_fb_pending',hash('sha256',$state));set_transient('wgpp_fb_oauth_'.hash('sha256',$state),$record,600);});
            wp_redirect('https://www.facebook.com/'.$a['version'].'/dialog/oauth?'.http_build_query(['client_id'=>$a['id'],'redirect_uri'=>self::callback_url(),'response_type'=>'code','state'=>$state,'config_id'=>$a['config_id']],'','&',PHP_QUERY_RFC3986));exit;
        }catch(RuntimeException $e){self::finish($e->getMessage());}
    }
    public static function validate_state($record,$c,$state,$pending,$app,$uid,$session){
        if(!is_array($record) || ($record['company'] ?? 0)!==$c['id'] || ($record['user'] ?? 0)!==$uid || ($record['expires'] ?? 0)<=time() || !hash_equals($record['session'] ?? '',hash('sha256',$session)) || !hash_equals($record['app'] ?? '',self::signature($app)) || !hash_equals($pending,hash('sha256',$state))){throw new RuntimeException('Facebook authorization expired or belongs to a different company/session. Start again.');}
    }
    public static function callback(){
        nocache_headers();header('Referrer-Policy: no-referrer');try{$c=self::owner();$a=self::app();$state=$_GET['state'] ?? '';$code=$_GET['code'] ?? '';
            if(!is_string($state) || !preg_match('/^[a-f0-9]{64}$/D',$state) || !is_string($code) || strlen($code)>4096){throw new RuntimeException('Invalid Facebook authorization response.');}
            WGPP_Native_Reviews::locked($c['id'],static function()use($c,$a,$state){$key='wgpp_fb_oauth_'.hash('sha256',$state);$r=get_transient($key);self::validate_state($r,$c,$state,(string)get_post_meta($c['id'],'_wgpp_fb_pending',true),$a,get_current_user_id(),wp_get_session_token());delete_transient($key);self::save_meta($c['id'],'_wgpp_fb_pending','processing:'.hash('sha256',$state));});
            if(!$code){throw new RuntimeException('Facebook authorization was canceled.');}
            $short=self::get($a,'oauth/access_token',['client_id'=>$a['id'],'client_secret'=>$a['secret'],'redirect_uri'=>self::callback_url(),'code'=>$code]);
            if(!is_string($short['access_token'] ?? null) || !$short['access_token']){throw new RuntimeException('Facebook did not return an access token.');}
            $long=self::get($a,'oauth/access_token',['grant_type'=>'fb_exchange_token','client_id'=>$a['id'],'client_secret'=>$a['secret'],'fb_exchange_token'=>$short['access_token']]);
            if(!is_string($long['access_token'] ?? null) || !$long['access_token']){throw new RuntimeException('Meta did not return a User token.');}
            $debug=self::get($a,'debug_token',['input_token'=>$long['access_token']],$a['id'].'|'.$a['secret']);$long['expires_in']=self::token_lifetime($debug,$a,time());
            self::validate_permissions(self::get($a,'me/permissions',[],$long['access_token']));
            WGPP_Native_Reviews::locked($c['id'],static function()use($c,$a,$state,$long){self::owner();if(get_post_meta($c['id'],'_wgpp_fb_pending',true)!=='processing:'.hash('sha256',$state) || self::signature(self::app())!==self::signature($a)){throw new RuntimeException('Facebook application or connection changed. Start again.');}
                self::save_meta($c['id'],self::AUTH,self::encrypt(['token'=>$long['access_token'],'expires'=>time()+(int)$long['expires_in'],'app'=>self::signature($a)],'company:'.$c['id'].':auth'));foreach([self::CHOICES,self::PAGE,self::CACHE,WGPP_IG_Reports::ACCOUNT,WGPP_IG_Reports::CACHE,'_wgpp_fb_pending'] as $key){delete_post_meta($c['id'],$key);}
            });self::finish('Facebook authorization saved. Load available Pages, then select the Page belonging to this company.');
        }catch(RuntimeException $e){self::finish($e->getMessage());}
    }
    public static function page_candidates($body){
        if(!is_array($body['data'] ?? null)){throw new RuntimeException('Unexpected Facebook Page list.');}$pages=[];
        foreach($body['data'] as $p){if(!is_string($p['id'] ?? null) || !preg_match('/^[1-9][0-9]{0,29}$/D',$p['id']) || !is_string($p['name'] ?? null) || !is_string($p['access_token'] ?? null) || !$p['access_token']){throw new RuntimeException('Unexpected Facebook Page credentials.');}
            if(!is_array($p['tasks'] ?? null)){throw new RuntimeException('Facebook Page analytics tasks were not returned.');}if(!array_intersect(['ANALYZE','MANAGE','PROFILE_PLUS_ANALYZE','PROFILE_PLUS_FULL_CONTROL'],$p['tasks'] ?? [])){continue;}$pages[$p['id']]=['id'=>$p['id'],'name'=>$p['name'],'token'=>$p['access_token']];}
        $next=!empty($body['paging']['next']);$cursor=$next?($body['paging']['cursors']['after'] ?? ''):'';if($next && (!is_string($cursor) || !$cursor || strlen($cursor)>2000)){throw new RuntimeException('Facebook pagination cursor is unavailable.');}
        $tasks=[];foreach($body['data'] as $p){foreach(($p['tasks'] ?? []) as $task){if(is_string($task) && preg_match('/^[A-Z_]+$/D',$task)){$tasks[]=$task;}}}
        return ['pages'=>$pages,'after'=>$cursor,'returned'=>count($body['data']),'tasks'=>array_values(array_unique($tasks))];
    }
    public static function discover(){
        check_admin_referer('wgpp_fb_discover');try{$c=self::owner();$a=self::app();$auth=self::decrypt(get_post_meta($c['id'],self::AUTH,true) ?: '','company:'.$c['id'].':auth');
            if($auth['app']!==self::signature($a) || $auth['expires']<time()+60){throw new RuntimeException('Reconnect Facebook to refresh Page selection.');}
            $saved=get_post_meta($c['id'],self::CHOICES,true);$choices=$saved?self::decrypt($saved,'company:'.$c['id'].':choices'):['pages'=>[],'after'=>''];
            $params=['fields'=>'id,name,access_token,tasks','limit'=>100];if($choices['after']){$params['after']=$choices['after'];}
            $next=self::page_candidates(self::get($a,'me/accounts',$params,$auth['token']));
            WGPP_Native_Reviews::locked($c['id'],static function()use($c,$a,$auth,$choices,$next){self::owner();$latest=self::decrypt(get_post_meta($c['id'],self::AUTH,true) ?: '','company:'.$c['id'].':auth');if($latest!==$auth){throw new RuntimeException('Facebook authorization changed. Load Pages again.');}$merged=array_replace($choices['pages'],$next['pages']);if(count($merged)>500){throw new RuntimeException('Pilot supports up to 500 accessible Pages. Use an account authorized for the needed Pages.');}self::save_meta($c['id'],self::CHOICES,self::encrypt(['pages'=>$merged,'after'=>$next['after']],'company:'.$c['id'].':choices'));});self::finish($next['pages']?(get_post_meta($c['id'],self::PAGE,true)?'Available Facebook Pages refreshed. Your saved company Page remains connected; choose a different Page only to change it.':'Available Facebook Pages loaded. Select the company Page below.'):'Facebook returned '.$next['returned'].' Pages; none passed the analytics-access check. Returned task codes: '.implode(', ',$next['tasks']).'. Check the authorized Page selection and analytics access.');
        }catch(RuntimeException $e){self::finish($e->getMessage());}
    }
    public static function select(){
        check_admin_referer('wgpp_fb_select');try{$c=self::owner();$a=self::app();$id=$_POST['fb_page'] ?? '';if(!is_string($id) || !preg_match('/^[1-9][0-9]{0,29}$/D',$id)){throw new RuntimeException('Select an authorized Facebook Page.');}
            $auth=get_post_meta($c['id'],self::AUTH,true);$data=self::decrypt($auth ?: '','company:'.$c['id'].':auth');if($data['app']!==self::signature($a)){throw new RuntimeException('Facebook application changed. Reconnect.');}
            $choices=self::decrypt(get_post_meta($c['id'],self::CHOICES,true) ?: '','company:'.$c['id'].':choices');$page=$choices['pages'][$id] ?? null;if(!$page){throw new RuntimeException('Select a Page from this company’s authorized list.');}
            $probe=self::get($a,$id,['fields'=>'id,name'],$page['token']);if(($probe['id'] ?? '')!==$id){throw new RuntimeException('Page identity could not be verified.');}
            WGPP_Native_Reviews::locked($c['id'],static function()use($c,$a,$auth,$page,$probe){self::owner();if(get_post_meta($c['id'],self::AUTH,true)!==$auth || self::signature(self::app())!==self::signature($a)){throw new RuntimeException('Facebook authorization changed. Reconnect.');}$page['name']=$probe['name'] ?? $page['name'];$page['app']=self::signature($a);$page['grant']=bin2hex(random_bytes(16));self::save_meta($c['id'],self::PAGE,self::encrypt($page,'company:'.$c['id'].':page'));delete_post_meta($c['id'],self::CACHE);delete_post_meta($c['id'],self::CHOICES);delete_post_meta($c['id'],WGPP_IG_Reports::ACCOUNT);delete_post_meta($c['id'],WGPP_IG_Reports::CACHE);});self::finish('Facebook Page selected. Open Facebook Page performance in the Report to collect the pilot metric.');
        }catch(RuntimeException $e){self::finish($e->getMessage());}
    }
    public static function instagram(){check_admin_referer('wgpp_fb_instagram');try{$c=self::owner();$a=self::app();$authSaved=get_post_meta($c['id'],self::AUTH,true);$auth=self::decrypt($authSaved ?: '','company:'.$c['id'].':auth');$pageSaved=get_post_meta($c['id'],self::PAGE,true);$page=self::decrypt($pageSaved ?: '','company:'.$c['id'].':page');if($auth['app']!==self::signature($a) || $page['app']!==self::signature($a) || $auth['expires']<time()+60){throw new RuntimeException('Reconnect Meta and select the Facebook Page first.');}$permissions=self::get($a,'me/permissions',[],$auth['token']);$granted=[];foreach(($permissions['data'] ?? []) as $p){if(($p['status'] ?? '')==='granted'){$granted[]=$p['permission'];}}if(array_diff(self::IG_SCOPES,$granted)){throw new RuntimeException('Instagram needs instagram_basic and instagram_manage_insights in the Meta login configuration. Reconnect Facebook to authorize these read permissions, select the Page, then connect Instagram.');}$body=self::get($a,$page['id'],['fields'=>'instagram_business_account'],$auth['token']);$id=$body['instagram_business_account']['id'] ?? '';if(!is_string($id) || !preg_match('/^[1-9][0-9]{0,29}$/D',$id)){throw new RuntimeException('No Instagram professional account was returned for the selected Facebook Page. Check the Page-to-Instagram link and your access.');}$profile=self::get($a,$id,['fields'=>'id,username'],$auth['token']);if(($profile['id'] ?? '')!==$id || !is_string($profile['username'] ?? null)){throw new RuntimeException('Instagram account identity could not be verified.');}WGPP_Native_Reviews::locked($c['id'],static function()use($c,$a,$authSaved,$pageSaved,$id,$profile){self::owner();if(get_post_meta($c['id'],self::AUTH,true)!==$authSaved || get_post_meta($c['id'],self::PAGE,true)!==$pageSaved || self::signature(self::app())!==self::signature($a)){throw new RuntimeException('Meta connection changed. Try connecting Instagram again.');}self::save_meta($c['id'],WGPP_IG_Reports::ACCOUNT,self::encrypt(['id'=>$id,'username'=>$profile['username'],'auth'=>hash('sha256',$authSaved)],'company:'.$c['id'].':instagram'));delete_post_meta($c['id'],WGPP_IG_Reports::CACHE);});self::finish('Instagram connected: @'.$profile['username'].'. Open Instagram in the Report.');}catch(RuntimeException $e){self::finish($e->getMessage());}}
    public static function ig_disconnect(){check_admin_referer('wgpp_fb_ig_disconnect');try{$c=self::owner();WGPP_Native_Reviews::locked($c['id'],static function()use($c){self::owner();delete_post_meta($c['id'],WGPP_IG_Reports::ACCOUNT);delete_post_meta($c['id'],WGPP_IG_Reports::CACHE);});self::finish('Instagram selection and cached reports removed.');}catch(RuntimeException $e){self::finish($e->getMessage());}}
    public static function disconnect(){check_admin_referer('wgpp_fb_disconnect');try{$c=self::owner();WGPP_Native_Reviews::locked($c['id'],static function()use($c){self::owner();foreach([self::AUTH,self::CHOICES,self::PAGE,self::CACHE,WGPP_IG_Reports::ACCOUNT,WGPP_IG_Reports::CACHE,'_wgpp_fb_pending'] as $key){delete_post_meta($c['id'],$key);}});self::finish('Facebook authorization and cached Page reports removed from this company. Remove the app in Meta Business Integrations to revoke provider access.');}catch(RuntimeException $e){self::finish($e->getMessage());}}
    private static function form($op,$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wgpp_fb_'.$op);echo '<input type="hidden" name="action" value="wgpp_fb_'.esc_attr($op).'"><button>'.esc_html($label).'</button></form>';}
    public static function render(){
        $c=WGPP_Company::context();if(!$c){return '';}$a=null;try{$a=self::app();}catch(RuntimeException $e){}$authorized=(bool)get_post_meta($c['id'],self::AUTH,true);$selected=null;try{$saved=get_post_meta($c['id'],self::PAGE,true);if($saved){$selected=self::decrypt($saved,'company:'.$c['id'].':page');}}catch(RuntimeException $e){}
        ob_start();echo '<details class="wgpa-import" data-connection="facebook"><summary>Facebook'.($selected?' · Connected — '.esc_html($selected['name']):($authorized?' · Choose company Page':' · Not connected')).'</summary><p>Reporting pilot. This connector only reads data. Meta requires business_management for this Pages use case; that provider permission can read and write business assets, but the connector does not call management or write endpoints. It also requests Page listing, Page read engagement and insights. No Page publishing, messaging or advertising-management permissions are requested.</p><p>'.($selected?'Selected Page: '.esc_html($selected['name']):($authorized?'Authorized. Select your company Page below.':'Facebook is not connected.')).'</p>';
        if(WGPP_Company::can('connections')){if($a){self::form('start',$authorized?'Change authorized Pages':'Connect Facebook');}else{echo '<p>A site administrator must configure the Westgate Meta app below.</p>';}
            if($authorized){self::form('discover','Load available Pages');try{$envelope=get_post_meta($c['id'],self::CHOICES,true);$choices=$envelope?self::decrypt($envelope,'company:'.$c['id'].':choices'):null;}catch(RuntimeException $e){$choices=null;}
                if($authorized){echo '<p class="wgpa-small-note">Page missing? Choose <strong>Change authorized Pages</strong>, then <strong>Edit settings</strong> in Meta and include the company Page. Keep existing customer Pages selected. Return here and load Pages again.</p>';}if(!empty($choices['pages'])){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wgpp_fb_select');echo '<input type="hidden" name="action" value="wgpp_fb_select"><label>Company Facebook Page <select name="fb_page" required><option value="">Choose this company’s Page</option>';foreach($choices['pages'] as $p){echo '<option value="'.esc_attr($p['id']).'"'.(($selected['id']??'')===$p['id']?' selected':'').'>'.esc_html($p['name']).'</option>';}echo '</select></label><button>Use this Page</button></form>';if($choices['after']){self::form('discover','Load more Pages');}}
                self::form('disconnect','Disconnect Facebook');}}
        if(is_admin() && current_user_can('manage_options')){echo '<details><summary>Westgate Facebook application settings</summary><p>Create a business-type Meta app and a Facebook Login for Business configuration using a User access token and business_management, pages_show_list, pages_read_engagement, read_insights. Meta requires the broader business_management dependency; this connector is restricted to read requests. Use this exact OAuth redirect URI:</p><code>'.esc_html(self::callback_url()).'</code><p>Public customer access may require Meta App Review, business/access verification and privacy/data-deletion information. Do not put the app secret into chat.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wgpp_fb_settings');echo '<input type="hidden" name="action" value="wgpp_fb_settings">';foreach(['id'=>'Meta app ID','config_id'=>'Facebook Login for Business configuration ID','version'=>'Graph API version'] as $key=>$label){echo '<p><label>'.esc_html($label).' <input name="fb_'.esc_attr($key).'" value="'.esc_attr($a[$key] ?? ($key==='version'?'v25.0':'')).'" required></label></p>';}echo '<p><label>App secret <input name="fb_secret" type="password" autocomplete="new-password"></label></p><p>Leave blank to retain the existing secret. Only site administrators manage application credentials.</p><button>Save Facebook application</button></form></details>';}
        $ig=null;try{$igSaved=get_post_meta($c['id'],WGPP_IG_Reports::ACCOUNT,true);if($igSaved){$ig=self::decrypt($igSaved,'company:'.$c['id'].':instagram');}}catch(RuntimeException $e){}
        echo '</details><details class="wgpa-import" data-connection="instagram"><summary>Instagram'.($ig?' · Connected — @'.esc_html($ig['username']):' · Not connected').'</summary>';
        if($ig){echo '<div style="margin:12px 0;padding:12px 16px;border:1px solid #a5cdb8;border-radius:6px;background:#eef8f1;color:#225b3b"><strong>✓ Instagram connected · @'.esc_html($ig['username']).'</strong><br><span style="font-size:14px">Connection saved for '.esc_html($c['name']).'. View Instagram performance in the Report tab.</span></div>';}
        else{echo '<p>Connect the professional Instagram account linked to this company’s Facebook Page.</p>';}
        if(WGPP_Company::can('connections')){if($selected){self::form('instagram',$ig?'Refresh saved connection':'Connect linked Instagram');}else{echo '<p>Select this company’s Facebook Page above, then connect Instagram.</p>';}if($ig){self::form('ig_disconnect','Disconnect Instagram');}}
        echo '<details style="margin-top:12px"><summary style="padding:8px 12px;font-size:13px;background:#0b4b71;color:#fff">About this connection</summary><p class="wgpa-small-note">Instagram reporting reads the professional account linked to the selected Facebook Page. Meta permissions: instagram_basic and instagram_manage_insights. Publishing, comments, messages and ads permissions are not requested.</p></details></details>';return ob_get_clean();
    }
}
